import { randomUUID } from "node:crypto";
import { NotFoundError, ValidationError } from "../domain/errors";
import { createProject, type Project } from "../domain/project";
import type { ProjectRepository, TaskFilter, TaskRepository, UserRepository } from "../domain/repositories";
import { assignTask, createTask, markTaskDone, type Task, type TaskStatus } from "../domain/task";
import { createUser, type User } from "../domain/user";

export interface CreateTaskCommand {
  projectId: string;
  title: string;
  description: string;
  dueDate?: Date | null;
  status?: TaskStatus;
  assigneeId?: string | null;
}

export class TaskManagementService {
  constructor(
    private readonly users: UserRepository,
    private readonly projects: ProjectRepository,
    private readonly tasks: TaskRepository,
  ) {}

  createUser(name: string): User {
    const user = createUser(randomUUID(), name);
    this.users.save(user);
    return user;
  }

  createProject(name: string): Project {
    const project = createProject(randomUUID(), name);
    this.projects.save(project);
    return project;
  }

  listProjects(): Project[] {
    return this.projects.findAll();
  }

  createTask(cmd: CreateTaskCommand): Task {
    this.requireProject(cmd.projectId);
    if (cmd.assigneeId) this.requireUser(cmd.assigneeId);
    const task = createTask({ ...cmd, id: randomUUID() });
    this.tasks.save(task);
    return task;
  }

  assignTask(taskId: string, assigneeId: string): Task {
    if (!assigneeId) throw new ValidationError("assigneeId is required");
    const task = this.requireTask(taskId);
    this.requireUser(assigneeId);
    const updated = assignTask(task, assigneeId);
    this.tasks.save(updated);
    return updated;
  }

  listTasks(projectId: string, filter: TaskFilter): Task[] {
    this.requireProject(projectId);
    return this.tasks.findByProject(projectId, filter);
  }

  markDone(taskId: string): Task {
    const updated = markTaskDone(this.requireTask(taskId));
    this.tasks.save(updated);
    return updated;
  }

  private requireProject(id: string): Project {
    const p = this.projects.findById(id);
    if (!p) throw new NotFoundError(`Project ${id} not found`);
    return p;
  }

  private requireUser(id: string): User {
    const u = this.users.findById(id);
    if (!u) throw new NotFoundError(`User ${id} not found`);
    return u;
  }

  private requireTask(id: string): Task {
    const t = this.tasks.findById(id);
    if (!t) throw new NotFoundError(`Task ${id} not found`);
    return t;
  }
}

=====SOURCE-END=====

